  INSERT INTO public.inventory_entries(
    project_id,category,description,quantity,unit,unit_cost,total_amount,
    paid_amount,balance_amount,date_purchase,supplier,reference_no,input_by_name,custom_data
  )
  SELECT
    v_project_id,s.category,s.description,s.quantity,s.unit,s.unit_cost,s.total_amount,
    s.total_amount,0,s.date_purchase,s.supplier,s.reference_no,
    'Imported Existing Inventory',s.custom_data
  FROM src s
  WHERE NOT EXISTS (
    SELECT 1 FROM public.inventory_entries i
    WHERE i.project_id=v_project_id
      AND i.custom_data->>'import_key'=s.import_key
      AND i.custom_data->>'import_batch'='melendres_inventory_20260929'
  );

  IF to_regprocedure('public.bump_system_release(text)') IS NOT NULL THEN
    PERFORM public.bump_system_release('v28.7 melendres existing inventory imported + project cost totals');
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';

SELECT
  p.project_name,
  sum(CASE WHEN i.category='Materials' THEN i.total_amount ELSE 0 END) AS materials_total,
  sum(CASE WHEN i.category='Labor' THEN i.total_amount ELSE 0 END) AS labor_total,
  sum(CASE WHEN i.category='Overhead' THEN i.total_amount ELSE 0 END) AS overhead_total,
  sum(i.total_amount) AS grand_total,
  count(*) AS imported_rows
FROM public.inventory_entries i
JOIN public.projects p ON p.id=i.project_id
WHERE (i.custom_data->>'import_batch')='melendres_inventory_20260929'
GROUP BY p.project_name;
